# Define the possible values for a near number (based on constraints n<=5, a<=3)
def generate_near_numbers():
    numbers = set()
    for n in range(1, 6):
        for a in range(1, 4):
            numbers.add(n**a + 1)
    return sorted(list(numbers))

Near_Numbers = generate_near_numbers()
print(f"Possible Near Numbers: {Near_Numbers}")

# Find solutions (B, T, S) such that B + T = S
solutions = []
for B in Near_Numbers:
    for T in Near_Numbers:
        S_candidate = B + T
        if S_candidate in Near_Numbers:
            S = S_candidate
            solutions.append((B, T, S))

print(f"\nFound solutions (B, T, S): {solutions}")

# Calculate the sum required: Sum of (B_i + T_i + S_i)
total_sum = 0
for B, T, S in solutions:
    total_sum += (B + T + S)

print(f"\nTotal Sum of (B+T+S): {total_sum}")

