def solve_near_numbers():
    N_B_options = range(1, 6)
    A_options = range(1, 4)
    N_T_options = range(1, 6)
    B_options = range(1, 4)
    N_S_options = range(1, 6)
    C_options = range(1, 4)

    total_sum = 0
    solution_count = 0

    for nB in N_B_options:
        for a in A_options:
            B = nB**a + 1
            for nT in N_T_options:
                for b in B_options:
                    T = nT**b + 1
                    for nS in N_S_options:
                        for c in C_options:
                            S = nS**c + 1

                            if B + T == S:
                                solution_count += 1
                                triple_sum = B + T + S
                                total_sum += triple_sum

    return solution_count, total_sum

solution_count, total_sum = solve_near_numbers()
print(f"Number of solutions (k): {solution_count}")
print(f"Total sum of (B_i + T_i + S_i): {total_sum}")
